<?php require dirname(__DIR__).'/inc/page_helpers.php';login_required();
if(page_post()){check_csrf();$title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));$launch=trim((string)($_POST['launch_url']??''));
