$q=$db->prepare('INSERT INTO games(creator_id,title,description,launch_url) VALUES(?,?,?,?)');$q->execute([$currentUser['id'],$title,$description,$launch?:null]);notice('Place created.');go('/PlaceItem.php?id='.$db->lastInsertId());}
page_start('Create Place');?><section class="Panel"><h1>Create a Place</h1><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Place name<input name="title" maxlength="120" required></label><label>Description<textarea name="description" rows="5"></textarea></label><label>Playable HTTPS URL (optional)<input type="url" name="launch_url" placeholder="https://example.com/game"></label><button class="Button">Create Place</button></form><p>HTTPS links can open browser-playable experiences. This does not launch the original Roblox 2008 client.</p></section><?php page_end();?>